insert into support_resources (id, title, category, summary, body, source_label, published)
values
  ('resource-call-care-team', 'Preparing for your next appointment', 'appointments', 'A short checklist to help you make the most of time with your care team.', 'Before the visit, write down your most important concerns and any changes since your last appointment. Bring an up-to-date medication list, recent test results if available, and the questions you want answered. Ask who to contact if symptoms change after you leave. Ask your clinician to explain anything that is unclear and to confirm the next steps in writing.', 'CancerCompanion educational content', true),
  ('resource-medication-list', 'Keeping a current medication list', 'medications', 'A practical way to keep your care team informed about medicines and supplements.', 'Record the name, dose, schedule, and prescribing clinician for each medicine. Include over-the-counter products, vitamins, and supplements. Bring the list to appointments and update it when your care team changes a medicine. Do not start, stop, or change a prescribed treatment based on this checklist; confirm changes with your clinician or pharmacist.', 'CancerCompanion educational content', true),
  ('resource-symptom-diary', 'Tracking symptoms between visits', 'wellbeing', 'A simple record can help you describe patterns and changes accurately.', 'Note when a symptom began, how often it occurs, how severe it feels, what makes it better or worse, and whether it affects sleep, eating, movement, or daily activities. Include your temperature when relevant and use the symptom scale your care team recommends. Contact your care team promptly about new, worsening, or concerning symptoms; seek emergency help for urgent or life-threatening symptoms.', 'CancerCompanion educational content', true),
  ('resource-support-network', 'Building a support network', 'caregivers', 'Small, specific requests can make it easier for friends and family to help.', 'Consider asking trusted people for practical help such as transport, meals, childcare, collecting prescriptions, or attending appointments. Decide what health information you are comfortable sharing, and agree on who may receive updates. You can change your mind about sharing at any time.', 'CancerCompanion educational content', true),
  ('resource-emotional-support', 'Finding emotional support', 'wellbeing', 'Emotional support is part of care, and it can look different for each person.', 'You may find support through a counsellor, oncology social worker, peer group, spiritual-care professional, or trusted person. Tell your care team when worry, low mood, fear, or sleep difficulties are becoming hard to manage. Ask what support services are available through your treatment centre or community.', 'CancerCompanion educational content', true),
  ('resource-second-opinion', 'Asking about a second opinion', 'treatment', 'You can ask your care team how another specialist might review your diagnosis or treatment options.', 'A second opinion may help you understand your diagnosis, available treatment approaches, clinical trials, or the benefits and risks of options. Ask whether your records, pathology reports, and imaging can be shared with the reviewing specialist. Do not delay urgent care while arranging another opinion; discuss timing with your treating team.', 'CancerCompanion educational content', true)
